import numpy as np

def detect_hallucinations(generated, source, nli_model):
    claims = [s.strip() for s in generated.split('.') if len(s.strip()) > 10]
    hallucinations = 0
    for claim in claims:
        result = nli_model(premise=source, hypothesis=claim)
        if result == 'contradiction':
            hallucinations += 1
    hallucination_rate = hallucinations / max(len(claims), 1)
    return hallucination_rate
